<div class="section"><div class="section-title">Cliente e contato</div><div class="grid"><div class="field"><b>Cliente / cadastro</b><?php echo os_e($o['person_name_snapshot']?:'Consumidor final'); ?></div><div class="field"><b>CPF/CNPJ</b><?php echo os_e($o['person_document_snapshot']); ?></div><div class="field"><b>Contato</b><?php echo os_e(($o['contact_name'] ?? '') ?: ($o['person_name_snapshot'] ?? '')); ?></div><div class="field"><b>Telefone / WhatsApp</b><?php echo os_e(($o['contact_phone'] ?? '') ?: ($o['person_phone_snapshot'] ?? '')); ?></div><?php if($o['expected_at']): ?><div class="field"><b>Previsão</b><?php echo date('d/m/Y H:i',strtotime($o['expected_at'])); ?></div><?php endif; ?></div></div>
<?php if($o['reported_problem']): ?><div class="section"><div class="section-title">Solicitação</div><div class="notes"><?php echo os_e($o['reported_problem']); ?></div></div><?php endif; ?>
<?php if($fields): ?><div class="section"><div class="section-title">Dados da O.S.</div><div class="grid"><?php foreach($fields as $f): $fv=osp_field_value($f,$optionLabels); if($fv==='')continue; ?><div class="field"><b><?php echo os_e($f['label']); ?></b><?php echo $f['input_type']==='password'?'<span class="secret">••••••</span>':os_e($fv); ?></div><?php endforeach; ?></div></div><?php endif; ?>
<?php if($damagePoints): ?><div class="section"><div class="section-title"><?php echo os_e($damageTitle); ?></div><div class="damage-layout"><div class="damage-print-map"><img src="<?php echo os_e($damageMapSrc); ?>" alt="<?php echo os_e($damageMapAlt); ?>"><?php foreach($damagePoints as $idx=>$dp): ?><span class="damage-print-marker" style="left:<?php echo number_format((float)$dp['position_x'],4,'.',''); ?>%;top:<?php echo number_format((float)$dp['position_y'],4,'.',''); ?>%"><?php echo $idx+1; ?></span><?php endforeach; ?></div><table class="damage-legend"><thead><tr><th class="damage-num">#</th><th>Tipo</th><th>Detalhes da avaria</th></tr></thead><tbody><?php foreach($damagePoints as $idx=>$dp): ?><tr><td class="damage-num"><span class="damage-number"><?php echo $idx+1; ?></span></td><td><?php echo os_e(isset($damageTypes[$dp['damage_type']])?$damageTypes[$dp['damage_type']]:$dp['damage_type']); ?></td><td><?php echo os_e($dp['description']); ?><?php if(!empty($dp['photo_url'])): ?><img class="damage-print-photo" src="<?php echo os_e($dp['photo_url']); ?>" alt="Foto da avaria <?php echo $idx+1; ?>"><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><div class="muted" style="font-size:.78em;margin-top:4px">Fotos de avarias são evidências temporárias e podem ser removidas automaticamente 48 horas após a conclusão da O.S.</div></div><?php endif; ?>
<?php if($products || $printBlankItems): ?><div class="section"><div class="section-title">Produtos</div><table class="items"><thead><tr><th>Descrição</th><th class="num">Qtd.</th><?php if(!$printHidePrices): ?><th class="num hide72">Unit.</th><th class="num">Total</th><?php endif; ?></tr></thead><tbody><?php foreach(($printBlankItems?[]:$products) as $i): ?><tr><td><?php echo os_e($i['description_snapshot']); ?><?php $respName=os_item_responsible_name($i); if($respName!==''): ?><div class="muted">Vendedor/Técnico: <?php echo os_e($respName); ?></div><?php endif; ?><?php if($i['notes']): ?><div class="muted"><?php echo os_e($i['notes']); ?></div><?php endif; ?></td><td class="num"><?php echo number_format((float)$i['quantity'],2,',','.'); ?></td><?php if(!$printHidePrices): ?><td class="num hide72"><?php echo os_money($i['unit_price']); ?></td><td class="num"><?php echo os_money($i['total']); ?></td><?php endif; ?></tr><?php endforeach; ?><?php if($printBlankItems): for($br=0;$br<8;$br++): ?><tr class="print-handwrite"><td>&nbsp;</td><td></td><?php if(!$printHidePrices): ?><td></td><td></td><?php endif; ?></tr><?php endfor; endif; ?></tbody></table></div><?php endif; ?>
<?php if($services && !$printBlankItems): ?><div class="section"><div class="section-title">Serviços</div><table class="items"><thead><tr><th>Descrição</th><th class="num">Qtd.</th><?php if(!$printHidePrices): ?><th class="num hide72">Unit.</th><th class="num">Total</th><?php endif; ?></tr></thead><tbody><?php foreach($services as $i): ?><tr><td><?php echo os_e($i['description_snapshot']); ?><?php $respName=os_item_responsible_name($i); if($respName!==''): ?><div class="muted">Vendedor/Técnico: <?php echo os_e($respName); ?></div><?php endif; ?><?php if($i['notes']): ?><div class="muted"><?php echo os_e($i['notes']); ?></div><?php endif; ?></td><td class="num"><?php echo number_format((float)$i['quantity'],2,',','.'); ?></td><?php if(!$printHidePrices): ?><td class="num hide72"><?php echo os_money($i['unit_price']); ?></td><td class="num"><?php echo os_money($i['total']); ?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<?php if(!$printHidePrices): ?><div class="totals"><div><span>Total produtos</span><b><?php echo os_money($o['total_products']); ?></b></div><div><span>Total serviços</span><b><?php echo os_money($o['total_services']); ?></b></div><?php if((float)$o['discount_amount']>0): ?><div><span>Desconto</span><b>- <?php echo os_money($o['discount_amount']); ?></b></div><?php endif; ?><?php if((float)$o['addition_amount']>0): ?><div><span>Acréscimo</span><b><?php echo os_money($o['addition_amount']); ?></b></div><?php endif; ?><div class="grand"><span>Total geral</span><span><?php echo os_money($o['total_general']); ?></span></div></div><?php endif; ?>
<?php if($payments): ?><div class="section"><div class="section-title">Formas de pagamento previstas</div><?php foreach($payments as $p): ?><div><?php echo os_e($p['payment_label']); ?><?php if(!$printHidePrices): ?> — <?php echo os_money($p['amount']); ?><?php endif; ?><?php echo $p['due_date']?' — '.$p['due_date']:''; ?></div><?php endforeach; ?></div><?php endif; ?>
<?php if($o['diagnosis']): ?><div class="section"><div class="section-title">Diagnóstico</div><div class="notes"><?php echo os_e($o['diagnosis']); ?></div></div><?php endif; ?>
<?php if($o['customer_notes']): ?><div class="section"><div class="section-title">Observações</div><div class="notes"><?php echo os_e($o['customer_notes']); ?></div></div><?php endif; ?>
<?php if($settings['terms_text']): ?><div class="terms"><?php echo nl2br(os_e($settings['terms_text'])); ?></div><?php endif; ?>
<?php if((int)$settings['print_customer_signature']||(int)$settings['print_responsible_signature']): ?><div class="signatures"><?php if((int)$settings['print_customer_signature']): ?><div class="signature">Cliente</div><?php else: ?><div></div><?php endif; ?><?php if((int)$settings['print_responsible_signature']): ?><div class="signature">Responsável</div><?php endif; ?></div><?php endif; ?>
</div></body></html>
